    val MAP: Map<String, DuaText> = mapOf(
        "dua_breaking_fast" to DuaText("द्रुतं विरमयितुं", "पिपासा निवृत्ता, शिरासु आर्द्रता भवति, अल्लाहस्य इच्छानुसारं प्रतिफलं निश्चिता भवति।", "इफ्तार्-समये।", "सः पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् इत्येषः व्रतं विरमयित्वा एतत् उक्तवान्।"),
        "dua_new_clothes" to DuaText("नूतनवस्त्राणि धरतु।", "हे अल्लाहः, सर्वस्य स्तुतिः भवतः एव; त्वं मह्यं एतत् परिधानं कृतवान्। अहं तव हितं, तस्य सद्गुणं च याचयामि, तस्य दुष्टात्, तस्य अशुभात् च भवतः शरणं प्रार्थयामि।", "यदा नूतनवस्त्रं धरति (तस्य नामकरणम्, यथा शर्ट् अथवा पगडी)।", "नबिये सल्लल्लाहु अलैहि वसल्लम् इत्येषः नूतनवस्त्रं धरन् एतत् दुआम् अकरोत्। (वस्त्रधारणार्थं दैनिक-दुआ'वस्त्रधारणम्'इति अस्ति।)"),
        "dua_rabbana_atina" to DuaText("अस्मिन् जगते तथा परकाले च शुभं भवति।", "हे अस्माकं प्रभुः, अस्मिन् जगते अस्मान् सत्करं परकाले च सत्करं ददातु, अग्न्योः दण्डात् अस्मान् रक्षयतु।", "पैगम्बरस्य दुआ प्रायः कृतवती।", "एकम् दुआ यत् विश्वस्य परित्यागे च सर्वान् कल्याणान् सङ्गृहीयति।"),
        "dua_rabbi_zidni_ilma" to DuaText("ज्ञानवृद्धिः", "हे मम प्रभुः, ज्ञानम् वर्धय।", "ज्ञानवृद्धिः।", "अल्लाहः पैगम्बरं सൽह-अलैहि वस्लम् इत्यस्मै आज्ञापयत् यत् सः ज्ञानस्य अतिरिक्तं किमपि न याचयेत्।"),
        "dua_musa_sharh_sadr" to DuaText("चेस्ट् इत्यस्य उद्घाटनम् (मूसा ए. एस्.)", "हे मम प्रभुः, मम कृते मम वक्षस्थलं विस्तरेण, मम कार्यं सक्षमापय, मम भाषायाः गाठिः च अनावृत्तं, येन ते मम भाषणं ग्रहीष्यन्ति।", "परीक्षायाः पूर्वं, भाषणम् अथवा किमपि कठिनं कार्यं।", "पैगम्बरस्य मूसा (अ. स.) इत्यस्य दुआ-हृदयस्य शान्तिः, कार्ये सहजता च।"),
        "dua_la_tuzigh" to DuaText("हृदयस्य स्थिरतायां", "हे अस्माकं प्रभुः, त्वं अस्माभिः मार्गाय मा प्रेरय, अस्माभिः स्वकृपया सहाय मा मा। निःसन्देहं त्वं एव दाता।", "मार्गदर्शनस्य प्रति दृढतायाः कृते।", "विश्वासे दृढतया स्थितेः कृते दुआ।"),
        "dua_ya_muqallib" to DuaText("ओ टर्नर ऑफ़ हार्ट्स", "हे हृदय-परिवर्तकः, मम हृदयं भवतः धर्मस्य विषये दृढं कुरु।", "पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् इत्येषः प्रायः एतत् दुआम् अकरोत्।", "उम्म सलामाह् (रा.) इत्यस्य मतेन, पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् इत्यनेन प्रायः दुआः कृतवती।"),
        "dua_la_tuakhidhna" to DuaText("सूरह् अल्-बखरा इत्यस्य अन्तिमं पदम्।", "हे अस्माकं प्रभुः, यदि वयं विस्मृतवन्तः वा, अथवा असत्यं कृतवन्तः तर्हि अस्मान् मा दण्डयतु। हे अस्माकं प्रभुः, अस्माकम् पूर्व्वम् यान् आरोपितवान् तस्य सदृशं भारम् न धारयतु। हे अस्माकं प्रभुः, अस्माकम् अस्माकम् असह्यं भारम् न धारयतु। अस्माकम् क्षमतु, अस्माकम् क्षमतु, अस्माकम् करुणाम् कुरु। त्वं अस्माकं रक्षकः, अतः अविश्वासिनः जनानाम् विरुद्धं अस्माकम् सहायम् करोतु।", "निद्रायाः पूर्वं रात्रौ-सूरह्-अल्-बकाराह् इत्यस्य अन्तिमद्वयं श्लोकं।", "यः कश्चित् रात्रौ सूरह्-अल्-बकरा इत्यस्य अन्तिमद्वयं श्लोकं पठति, सः एव पर्याप्तः भविष्यति।"),
        "dua_visiting_sick" to DuaText("रोगिनः सन्दर्शयतः।", "अहं सर्वशक्तिमानः, सर्वशक्तिमानः सिंहासनस्य स्वामी, ईश्वरं प्रार्थयेते यत् भवतः उपचारं कुरु।", "सप्तवारं यदा रोगिणां प्रति दर्शनं भवति।", "यदि मृत्योः कालः न आगच्छति तर्हि अल्लाहः तं स्वस्थं करिष्यति।"),
        "dua_ruqyah_pain" to DuaText("शारीरिक-वेदनायाः कृते", "अहं यः दुष्टः तस्यां शक्त्या च आश्रयं प्रार्थयेम इति मम भावः, भयः च।", "यत्र यन्त्रणं भवति तत्र हस्तं स्थापयतु, तिस्रवारं बिस्मिल्ला इति वदतु, ततः सप्तवारं इदं दुआ वदतु।", "सः पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् इत्येषः उस्मान् इब्न् अबिल्-अस् (र) इत्यस्मै वेदनायाः कृते इदं उपदिशत्।"),
        "dua_ruqyah_nabawi" to DuaText("रोगिणां कृते भविष्यसूचकः रुक्या", "हे अल्लाहः, मानवजात्याः स्वामी! हानिं परिहर्य चिकित्सां करोतु, यतः त्वं एव रोगनिवारकः; भवतः उपचारस्य विना उपचारः नास्ति-एकः उपचारः यः रोगं न वदति।", "यदा रोगिनः हस्तं तस्य उपरि गच्छन्ति।", "सः पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् स्वपरिवारस्य रोगिणां सदस्यान् सन्दर्शयन् एतत् पठितवान्।"),
        "dua_kalimat_tammat" to DuaText("परिपूर्ण-शब्दैः शरणम् अन्विष्यत।", "ईश्वरस्य सृष्टौ दुष्टात् मुक्तात् तस्य सिद्धवाक्येषु शरणम् इच्छामि।", "यदा स्थाने वा सायङ्काले वा स्थातुं शक्यते।", "यः कश्चित् एकस्मिन् स्थाने स्थिते तथा इमां वदति, तावत् तस्य न हानिः भविष्यति।"),
        "dua_evil_eye" to DuaText("बालानां रक्षणम् (दुष्ट-नेत्रम्)", "अहं भवतः कृते प्रत्येकं शय़तानात्, प्रत्येकं विषाक्तात्, प्रत्येकं हानिकरं नेत्रं च ईश्वरस्य पूर्णवाक्येषु रक्षां याचामि।", "पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् हसन्-हुसेन् (र) इत्येतयोः उपरि इदं पठितवान्।", "बालानां दुष्टदृष्ट्या हान्या च रक्षणार्थं सुन्नत-दुआ (एकस्य बालस्य कृते'उधुका'इति वदति)।"),
        "dua_seeing_afflicted" to DuaText("विचारणकाले कस्मित् दृष्टः।", "सर्वस्य प्रशंसायाः अल्लाहस्य एव, यः भवतः परीक्षणात् मां रक्षितवान्, स्वस्य सृष्टेः अधिकांशभागस्य उपरि मम उपरि अनुग्रहं कृतवान्।", "विचारणकाले कस्मित् दृष्ट्वा (निश्शब्दतया स्वयमेव वदतु)।", "यः वदति सः तस्य विचारणात् सुरक्षितः अस्ति।"),
        "dua_istikhara" to DuaText("सलात्-अल-इस्तिकारा", "हे अल्लाह, अहं भवतः ज्ञानद्वारा सद्गुणम् अन्विष्यामि, अहं भवतः शक्त्या सामर्थ्यं अन्विष्यामि, तथा च भवतः महान् अनुग्रहं प्रार्थयामि। भवतः शक्तिः अस्ति, मम किमपि नास्ति। भवान् जानाति, अहं न जानामि, तथा च अदृश्यं च जानाति। हे अल्लाहः, यदि भवतः ज्ञानेन एतत् कार्यं (मनसि आनयत्) मम धर्मस्य, मम जीवनस्य, मम अन्तस्य च कृते उत्तमं भवति, तर्हि मम कृते तत् आदेशं करोतु, मम कृते सुलभं करोतु, मह्यं च आशीर्वादं करोतु। यदि भवतः ज्ञानेन एतत् कार्यं मम धर्मस्य, मम जीवनस्य, मम अन्तस्य च कृते अशुभं भवति, तर्हि मम समीपे तत् तिर्यन्तु, मम समीपे तत् दूरम् आनयन्तु, मम कृते यत्र यथा यथा यथा यथा यथा यथा भवेत् तत् सम्यक् आज्ञापयतु, ततः मह्यं सन्तुष्टं करोतु।", "स्व-प्रार्थनायाः राका-द्वयं कृत्वा, अनुमत-विषये सर्वोत्तमं यत् भवति तत् अन्वेष्टुं।", "पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् इत्ययं सहचरान् सर्वविषयेषु इस्तिकारा इति उपदिशत्, यतः सः तान् कुरान् इत्यस्य सूराह् इति उपदिशत्।"),
        "dua_allahumma_bika_asbahna" to DuaText("अल्लाहुम्मा बीका अस्बाह्ना", "हे अल्लाहः, वयं प्रातःकाले भवतः द्वारामपि प्रवेशं कुर्वन्तः, सायङ्काले च भवतः द्वारामपि जीवाम, भवतः द्वारामपि म्रियाम, भवतः कृते च पुनरुत्थानम्।", "प्रातःकाले।", "पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् आजाद् प्रातः सायङ्काले च वक्तुं सहचरान् उपदिशत्।"),
        "dua_allahumma_bika_amsayna" to DuaText("अल्लाहुम्मा बीका अम्सेना", "हे अल्लाहः, वयं सायङ्काले भवतः द्वारात् प्रवेशं कुर्वन्तः, प्रातःकाले च भवतः द्वारात् प्रवेशं कुर्वन्तः; वयं भवतः द्वारात् जीवामः, भवतः द्वारात् म्रियामः, भवतः प्रति प्रत्यागमनं भवति।", "सायङ्काले।", "पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् आजाद् प्रातः सायङ्काले च वक्तुं सहचरान् उपदिशत्।"),
        "dua_afiyah_morning" to DuaText("अफिया-इत्यस्य कृते प्रार्थयतु।", "हे अल्लाहः, अहं युष्मभ्यम् क्षमा याचिद्स्मि, संसारे च परकाले च कल्याणम्।", "पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् इत्येषः प्रातः सायं वा कदापि इदं दुआ न निष्कासयत्।", "कल्याणात् श्रेष्ठं किमपि न दत्तम्।"),
        "dua_afini_fi_badani" to DuaText("शरीरस्य, श्रवणस्य, दृष्टेः च स्वास्थ्यम्", "हे अल्लाह, मम शरीरस्य कल्याणम् करोतु। हे अल्लाह, मम श्रवणस्य कल्याणम् करोतु। हे अल्लाह, मम दृष्टेः कल्याणम् करोतु। त्वं विहाय अन्यः देवः नास्ति।", "प्रतिदिनं प्रातः सायङ्काले च त्रिवारं।", "स्वास्थ्यस्य, इन्द्रियानां रक्षणस्य च कृते दुआ।"),
        "dua_ya_hayyu_aslih" to DuaText("मम सर्वाणि कार्याणि परिष्करोतु।", "हे नित्यजीवः, हे निर्वाहकः, अहं भवतः दयया साहाय्यं याचयेते, मम सर्वकार्याणि सम्यक् करोतु, मम नेत्रक्षरणार्थं अपि न वदतु।", "पैगम्बरः सल्यी-अल-इस्लाम् फ़ातिमा (र) इत्यस्मै प्रातः सायङ्काले च उक्तुं उपदेशितवान्।", "प्रत्येकं विषये अल्लाहस्य साहाय्यं प्रार्थयतु।"),
        "dua_subhanallah_adada_khalqihi" to DuaText("जुवरिया इत्यस्य तसबिया (रा.)", "अल्लाहस्य महिमा भवति, तस्य सर्व-स्तुतिः तस्य एव अस्ति-यतान् तस्य सृष्टिः यतान् इच्छति, तस्य सिंहासनस्य भारः, तस्य वचनस्य शायिः च समानम्।", "प्रातःकाले त्रिवारं-धिक्रस्य घण्टायाः अपेक्षया भारकं भवति।", "एते चत्वारः वाक्यांशानि त्रिगुणितं वक्तुं प्रातःकालात् मध्यरात्रिमध्ये यावत् धिक्रः अधिकं भवति।"),
        "dua_salawat" to DuaText("दुरूद्-ए-इब्राहिमी", "हे अल्लाहः, मुहम्मद-स-अलैहि वस्लम्-वर्यस्य, मुहम्मद-वर्यस्य परिवारस्य च प्रार्थनां प्रेषय, यदा भवान् इब्राहिम-वर्यस्य, इब्राहिम-वर्यस्य च प्रार्थनां प्रेषितवान्, तदा भवान् प्रशंसनीयः, महिमावान् अस्ति। हे अल्लाहः, मुहम्मद-स-अलैहि वस्लम्-वर्यस्य, मुहम्मद-वर्यस्य च, यथा भवान् इब्राहिम-वर्यस्य, इब्राहिम-वरस्य च आशीर्वादं कृतवान्, तथैव भवन्तः प्रशंसनीयाः, महिमावान् च सन्ति।", "सൽमावत्-सः सल्हे-अलियेह्-सलाम् इत्यस्मै प्रार्थनायां तथा सर्वदा।", "यः एकदा सलावत् प्रेषयति, अल्लाहः तस्य उपरि दश करुणानि प्रेषयति (मुस्लिम् 408)।"),
        "dua_wudu_after" to DuaText("वुडु इत्यस्य अनन्तरं", "अहं साक्ष्यं ददामि यत् अल्लाहः विना, एकाकी, साझीदारः, पूजनीयः अधिकारः नास्ति, मुहम्मद् सल्लल्लाहु अलैहि वसल्लम् तस्य दासः, दूतः च अस्ति। हे अल्लाहः, पश्चात्तापिनः, स्वशुद्धाः च जनान् मम कृते स्थापय।", "वूडु-पूर्णतायाः अनन्तरं।", "स्वर्गस्य अष्टद्वाराणि तस्य कृते उद्घाटितानि सन्ति येन यः इच्छे सः प्रवेश्यते।"),
        "dua_wudu_before" to DuaText("वुडु इत्यस्य पूर्वं", "अल्लाहस्य नाम्नम्।", "यदा वूडु-आरम्भः भवति।", "यः तस्य उपरि अल्लाहस्य नाम न उल्लिखति तस्य कृते (पूर्णः) वुडु नास्ति।"),
        "dua_istiftah" to DuaText("उद्घाटना प्रार्थना (सना)", "हे अल्लाह, त्वं महिमाय, स्तुतिः च। भवतः नाम धन्यम्, भवतः महिमा श्रेष्ठम्, भवतः विना अन्यः देवः नास्ति।", "प्रार्थनायाः आरम्भे, उद्घाटना-तक्बीर् इत्यस्य अनन्तरं एव।", "सुन्नतः प्रार्थनायाः द्विवारं उद्घाटयति।"),
        "dua_ruku" to DuaText("रुकु मध्ये", "महिमाय मम प्रभूः, महती।", "रुकु-मध्ये न्यूनातिन्यूनं त्रिवारं।", "रुकू इत्यस्य सुन्नह्-तस्बिह् इति।"),
        "dua_sujood" to DuaText("सुजूद् मध्ये", "मह्यं भगवतः सर्वोच्चः इति महिमाय।", "सुजूद् इत्यस्मिन् न्यूनातिन्यूनं त्रिवारं।", "साष्टांगं कुर्वन् दासः स्वप्रभोः समीपस्थः भवति (मुस्लिम् 482)।"),
        "dua_rising_ruku" to DuaText("रुकू इत्यतः उद्गमः।", "यः तस्य स्तुतिं करोति सः अल्लाहस्य श्रोता भवति। हे अस्माकं प्रभुः, सर्वस्य स्तुतिः भवतः एव।", "यदा रुकु-तः उत्थीय, ऊर्ध्वं च स्थायते।", "यः'रब्बाना व लाकल्-हम्द्'इति दूतानां पापैः सह सङ्गमिष्यति तस्य पूर्वकालस्य पापानि क्षम्यन्ते।"),
        "dua_between_sajdas" to DuaText("द्वयोः सजदासयोः मध्ये", "हे मम प्रभुः, मा क्षमां करोतु। हे मम प्रभुः, मा क्षमां करोतु।", "द्वयोः साष्टांगयोः मध्ये उपविश्य।", "प्रणवेण मध्यस्थितस्य सुन्नत-दुआ।"),
        "dua_before_salam_four" to DuaText("चतुर्णां वस्तुभ्यः शरणम् (सलामात् पूर्वं)", "हे अल्लाहः, अहं नरकेः दण्डात्, समाध्याः दण्डात्, जीवनस्य मृत्योः च परीक्षणात्, मिथ्या-मसीहा (दज्जल्) इत्यस्य परीक्षणस्य दुष्टतायाः च शरणं प्रार्थये।", "अन्तिमस्य ताशाह्हुद् इत्यस्य, सलावत् इत्यस्य च अनन्तरं, सलाम् इत्यस्य पूर्वं।", "पैगम्बरः सल्लल्लाहु अलैहि वसल्लम् एताः चतुर्णां विषयेषु शरणं ग्रहीतुं आदिशत्।"),
        "dua_qunoot_witr" to DuaText("कुनूत्-इन-विट्र्", "हे अल्लाहः, यान् मार्गम् अददाति तेषु मम मार्गम् अनुचर, यान् कल्याणम् अददाति तेषु मम कल्याणम् अनुग्रहि, यान् भवतः परिचर्यायां निमग्नवान् तेषु मह्यं परिवीक्षणं करोतु, यान् दत्तवान् तस्मिन् मह्यं अनुग्रहितु, यान् दत्तवान् तस्य दुष्टात् मां रक्षयतु। त्वं आदेशं ददातु, यान् प्रति आज्ञां न दत्तवान्, यान् मित्रं करोति सः कदापि अपमानितः न भवति। हे अस्माकं प्रभुः, त्वं धन्यः, श्रेष्ठः च।", "विद्र्-प्रार्थनायां-पैगम्बरः सल्लल्लाहु अलैहि वस्लम् हसन् इब्न् अली (र. अ.) इत्यस्मै तत् उपदिशत्।", "विद्रस्य सुन्नह्-कुनूत् (हनाफ़ीसाम् मध्ये'अल्लाहुम्मा इन्ना नास्तानुका'इति अपि सुपरिचितम् अस्ति।)"),
        "dua_qunoot_hanafi" to DuaText("कुनूत् (अल्लाहुम्मा इन्ना नास्तानुका)", "हे अल्लाहः, वयं भवतः साहाय्यं, भवतः क्षमाः च प्रार्थयामः, वयं भवतः विश्वासम्, भवतः उपरि आश्रयं च कुर्वामः, उत्तमरूपेण भवतः स्तुतिं कुर्वामः, वयं भवतः आभारं कुर्वन्ति, कृतघ्नं न भवन्ति, यः भवतः अवज्ञा करोति तस्य त्यागं कुर्वन्ति। हे अल्लाहः, केवलं तव एव वयं पूज्यामः, तव शरणागति, प्रणामं च कुर्वामः, त्वरां प्रयतामः, भवतः दयायाः प्रतीक्षां कुर्वन्तः, भवतः दण्डस्य भीताः च भवन्तः। निःसन्देहं भवतः दण्डः अविश्वासिनः सम्मिलयिष्यति।", "विटर-- हनाफ़ीसानां अभ्यासः।", "कुनूत् इत्यस्मिन् उमर् (र) इत्यतः सूचितः।"),
        "dua_sleep_aslamtu" to DuaText("निद्रायाः पूर्वं अन्तिमशब्दानि", "हे अल्लाहः, अहं तव अधीनः अस्मि, मम कार्यं तव प्रति समर्पयामि, मम पीठं भवतः रक्षणार्थं समर्पयामि, भवतः आशया, भवतः भयात् च। भवतः विना किमपि आश्रयं नास्ति, न च पलायनम्। भवतः प्रकाशिते ग्रन्थे, भवतः प्रवक्त्रे, यस्मै भवान् प्रेषितवान्, अहं विश्वसामि।", "वूडु इत्यस्य अनन्तरं, दक्षिणभागे शयनं-निद्रायाः पूर्वं अन्तिमशब्दः।", "यदि सः तस्मिन् रात्रौ म्रियते तर्हि सः फितरा (इस्लाम्) दिने म्रियते।"),
        "dua_waking_night" to DuaText("रात्रौ जागते", "अल्लाहः विना, केवलं, साझीदारः, उपासने काचित् न अधिकारः अस्ति। तस्य आधिपत्यं, तस्य प्रशंसां च, सर्वविषयेषु च तस्य अधिकारः अस्ति। सर्व-प्रशंसां अल्लाहस्य एव, महिमां अल्लाहस्य एव, अल्लाहः अतिरिच्य उपासने काचित् अधिकारः नास्ति, अल्लाहः सर्वश्रेष्ठः, अल्लाहः विना शक्तिः वा शक्तिः वा नास्ति। हे अल्लाहः, मां क्षमि।", "रात्रौ जागते।", "तस्य दुआः प्रत्युत्तरं भवति, यदि सः वुडु-प्रार्थनां च करोति तर्हि तस्य प्रार्थना स्वीयते।"),
        "dua_hamm_ibn_masud" to DuaText("दुवा दुःखस्य कृते (इब्न मसूद)", "हे अल्लाहः, अहं भवतः दासः, भवतः दासस्य पुत्रः, भवतः दास्याः पुत्रः। मम अग्रबन्धः भवतः हस्ते अस्ति, मम विषये भवतः आदेशः प्रवर्तते, मम विषये भवतः आदेशः न्यायः अस्ति। यः भवतः नाम अस्ति, यः भवतः नामे अस्ति, यः भवतः ग्रन्थे प्रकटितः अस्ति, यः भवतः सृष्टिं शिक्षितः अस्ति, अदृश्यज्ञानात् च भवतः समीपे रक्षितः अस्ति, यः कुरान् मम हृदयस्य उत्सः, मम छातीः ज्योतिः, मम दुःखस्य निष्कासनं, मम चिन्तायाः प्रस्थानं च करोति इति अहं भवन्तं प्रार्थये।", "दुःखस्य दुःखस्य च स्थाने अल्लाहः आनन्दं स्थापयति।", "अल्लाहः तस्य चिन्तां दुःखं च नीत्वा तस्य स्थाने आनन्दं प्रददाति।"),
        "dua_difficulty_sahl" to DuaText("यदा किमपि कष्टम् अस्ति।", "हे अल्लाहः, यत् भवान् सुलभं करोति तस्य विना किमपि सुलभं नास्ति, यदि भवान् इच्छति तर्हि कठिनं सुलभं करोति।", "यदा किमपि कष्टम् अनुभवति।", "परीक्षासु, कठिनकार्येषु च सहजता।"),
        "dua_musibah" to DuaText("अपान् ए क्यालामिटी (इस्तिरजा)", "वयं अल्लाहस्य एव, तस्यै प्रत्यागमयाम। हे अल्लाहः, मम दुर्दशायां प्रतिफलं ददातु, मम स्थाने उत्तमं किमपि स्थापयतु।", "कस्यापि हानिः अथवा विपत्तेः विषये।", "अल्लाहः निश्चयेन उत्तमं किमपि ददाति-उम्-सलमा (रा) इत्ययम् पैगम्बरस्य कृते प्रदत्तम्।"),
        "dua_debt" to DuaText("ऋणमुक्तेः कृते", "हे अल्लाहः, त्वं निषिद्धं यत् निषिद्धं तत् प्रति यदृशं विधिं कृतवान् तत् मह्यं पर्याप्तं करोतु, तथा च भवतः अनुग्रहेण मह्यं भवतः अतिरिक्तं सर्वस्मात् मुक्तं करोतु।", "ऋणस्य शोधनार्थं-अली (रा) इत्यनेन शिक्षिता।", "ऋणं पर्वते इव भवति चेत् अल्लाहः तस्य शोधनं करिष्यति।"),
        "dua_anger" to DuaText("यदा क्रोधः भवति।", "शप्तात् शयतान् इत्यतः अहं अल्लाहस्य शरणं प्रार्थये।", "यदा क्रोधः भवति।", "सः पैगम्बरः (सः) अवदत् यदि सः इमां वदति तर्हि तस्य क्रोधः नीतः।"),
        "dua_waswasa" to DuaText("विश्वासे वासवासस्य विरुद्धं", "अहं अल्लाहस्य, तस्य दूतानां च विश्वासम् आचरामि।", "यदा विश्वासस्य विषये शैतानीः किंवदन्ति तदा भवति।", "यदा किंवदन्ती आगच्छति तदा इदं वदतु तत्र एव विरामं करोतु (अल्लाहस्य शरणं च याचतु)।"),
    )
}
